/* From Uiverse.io by mrhyddenn - Tags: button */
.__UIV_SCOPE__ button {
  background: none;
  border: none;
  padding: 15px 15px;
  border-radius: 10px;
}

.__UIV_SCOPE__ button:hover {
  background: rgba(170, 170, 170, 0.062);
  transition: 0.5s;
}

.__UIV_SCOPE__ button svg {
  color: #fff;
}
